// Evidence drawer: a card catalogue (one drawer per source note) and a 3-axis picker.
// World units ~1 px, x along the cabinet, y toward the front, z up.
// Every function takes the kit as `k`, so the build and the live page draw the same parts.

const W = {
  plate: { x: -134, y: -64, w: 268, d: 116, r: 6 },
  plateH: 10, footH: 5,
  cab: { x: -90, y: -50, w: 150, d: 50, r: 1.5 },
  plinthH: 6, cabTop: 112,
  cols: 3, rows: 3,
  innerX: -84, colW: 44, gapX: 3,
  innerZ: 12, rowH: 29, gapZ: 3,
  frontD: 3,
  open: 20, lift: 20,
  postX: [-122, 104], postW: 10, postY: 29, postD: 10, postTop: 178,
  rail: { y: 30, d: 8, z: 164, h: 8 },
  ramZ: 174, ramH: 6, ramLen: 32,
  homeY: 12, dockY: 3.8, mastOff: 31,
  gauge: { x: 83, y: -63, w: 34, d: 26, cx: 100, cy: -50, r: 14, post: 46 },
};
W.gaugeTop = W.gauge.post + 8;

const slot = (i) => {
  const col = i % W.cols, row = W.rows - 1 - Math.floor(i / W.cols);
  const x0 = W.innerX + col * (W.colW + W.gapX);
  const z0 = W.innerZ + row * (W.rowH + W.gapZ);
  return { col, row, x0, z0, cx: x0 + W.colW / 2, pz: z0 + 9 };
};
const mastX = (cx) => cx + W.mastOff;

// One drawer front, its label holder and (separately) its pull.
function front(k, P, i, o = 0) {
  const s = slot(i);
  const panel = { x: s.x0, y: o, w: W.colW, d: W.frontD, r: 1 };
  const holder = { x: s.cx - 9, y: o + W.frontD, w: 18, d: 0.7, r: 0.6 };
  const hz = s.z0 + W.rowH - 11;
  const fy = o + W.frontD + 0.7;
  const rules = [[-6.5, 3.5], [-6.5, 5.5], [-6.5, 1]].map(([a, b], n) => k.segment([s.cx + a, fy, hz + 5.2 - n * 1.6], [s.cx + b, fy, hz + 5.2 - n * 1.6], P)).join("");
  return [
    k.solidSvg(k.slabOf(panel, s.z0, W.rowH, P, 3, 0.8), { tone: "mid", inner: k.lineSvg(k.sideSeam(k.insetPlan(panel, -0.01), s.z0 + 3, P, 3), { tone: "faint" }) }),
    k.solidSvg(k.slabOf(holder, hz, 7, P, 2, 0.3), { tone: "lo" }),
    k.lineSvg(rules, { tone: "lo", free: true }),
    k.dotsSvg([k.iso([s.cx - 8, fy, hz + 6], P), k.iso([s.cx + 8, fy, hz + 6], P), k.iso([s.cx - 8, fy, hz + 1], P), k.iso([s.cx + 8, fy, hz + 1], P)], { size: 0.4 }),
  ].join("");
}
function pull(k, P, i, o = 0, tip = "") {
  const s = slot(i);
  const y = o + W.frontD;
  const post = (x) => k.solidSvg(k.slabOf({ x, y, w: 2, d: 3, r: 0.6 }, s.pz - 1, 2, P, 2), { tone: "mid", crease: "none" });
  const bar = k.solidSvg(k.slabOf({ x: s.cx - 8, y: y + 3, w: 16, d: 1.6, r: 0.8 }, s.pz - 1.2, 2.4, P, 3, 0.3), { tone: "hi", crease: "lo" });
  return post(s.cx - 7) + post(s.cx + 5) + tip + bar;
}

// The pulled drawer: only what is outside the cabinet is drawn, rebuilt each frame.
function pulled(k, P, i, o, lift, card) {
  const s = slot(i);
  const out = [];
  const corners = [[s.x0, 0, s.z0], [s.x0 + W.colW, 0, s.z0], [s.x0 + W.colW, 0, s.z0 + W.rowH], [s.x0, 0, s.z0 + W.rowH]].map((p) => k.iso(p, P));
  out.push(`<path class="ev-cavity" d="M${corners.map((p) => p.join(" ")).join("L")}Z"/>`);
  if (o > 0.6) {
    const from = Math.max(0, o - 44);
    const floor = { x: s.x0 + 1, y: from, w: W.colW - 2, d: o - from, r: 0.4 };
    out.push(k.solidSvg(k.slabOf(floor, s.z0 + 1, 1.2, P, 2), { tone: "lo" }));
    const wall = (x) => k.solidSvg(k.slabOf({ x, y: from, w: 1.2, d: o - from, r: 0.3 }, s.z0 + 2.2, 17, P, 2, 0.3), { tone: "mid" });
    out.push(wall(s.x0 + 1));
    for (let c = -40; c <= -14; c += 4.5) {
      const y = c + o;
      if (y < 0.4) continue;
      out.push(k.solidSvg(k.slabOf({ x: s.x0 + 4, y, w: W.colW - 8, d: 0.7, r: 0.2 }, s.z0 + 2.2, 19, P, 2), { tone: "lo", crease: "none" }));
    }
    const cy = -9.5 + o;
    if (cy > 0.4) out.push(evidenceCard(k, P, s, cy, lift, card));
    out.push(wall(s.x0 + W.colW - 2.2));
  }
  return out.join("");
}

// The lit card: rule lines for the note, highlighter bars for the cited lines.
function evidenceCard(k, P, s, y, lift, card) {
  const plan = { x: s.x0 + 4, y, w: W.colW - 8, d: 0.8, r: 0.2 };
  const z = s.z0 + 2.2 + lift;
  const h = 19;
  const top = z + h;
  const m = k.sideMatrix([plan.x, y + 0.8], top, P, "left");
  const lines = [2.6, 5, 7.4, 9.8, 12.2, 14.6, 17];
  const lens = [30, 26, 33, 22, 31, 27, 18];
  const marked = [1, 2, 4, 5].slice(0, card.cited);
  const share = card.reveal ?? 1;
  let face = "";
  marked.forEach((n, j) => {
    const grow = Math.min(1, Math.max(0, share * card.cited - j));
    if (grow > 0) face += `<rect class="ev-mark" x="1.4" y="${lines[n] - 1.05}" width="${(lens[n] + 0.6) * grow}" height="2.1"/>`;
  });
  if (card.gaps) face += `<rect class="ev-gap" x="1.4" y="${lines[6] - 1.05}" width="${lens[6] + 0.6}" height="2.1" style="opacity:${share}"/>`;
  face += `<path class="iso-line" data-tone="lo" data-free="" d="${lines.map((v, n) => `M2 ${v}H${2 + lens[n]}`).join("")}"/>`;
  face += `<path class="iso-line" data-tone="mid" d="M0 0.9H${plan.w}"/>`;
  return k.solidSvg(k.slabOf(plan, z, h, P, 2), { tone: "hi", lit: true, crease: "none" }) + `<g transform="${m}" class="ev-face">${face}</g>`;
}

// The picker: mast, head and hook (drawn before the rail), ram and carriage (after it).
function hookTip(k, P, g) {
  return k.solidSvg(k.slabOf({ x: g.cx + 1.4, y: g.y + 0.1, w: 2, d: 1.6, r: 0.4 }, g.z - 1, 3.4, P, 2), { tone: "hi" });
}
function mast(k, P, g) {
  const mx = g.x;
  const out = [];
  const headZ = g.z + 2.4;
  const finger = { x: g.cx + 1.4, y: g.y + 0.1, w: mx - 3 - g.cx - 1.4, d: 5.6, r: 0.6 };
  out.push(k.solidSvg(k.slabOf(finger, headZ, 1.6, P, 2, 0.3), { tone: "hi", crease: "lo" }));
  const head = { x: mx - 3.5, y: g.y + 1, w: 7, d: 7, r: 1 };
  out.push(k.solidSvg(k.slabOf(head, g.z - 1, 9, P, 3, 0.5), { tone: "hi", crease: "lo" }));
  out.push(k.dotsSvg([k.iso([mx - 2, g.y + 8, g.z + 6], P), k.iso([mx + 2, g.y + 8, g.z + 6], P)], { size: 0.4 }));
  out.push(k.solidSvg(k.slabOf({ x: mx - 1.6, y: g.y + 2.9, w: 3.2, d: 3.2, r: 1.2 }, g.z + 8, W.ramZ - g.z - 8, P, 3), { tone: "mid", inner: k.lineSvg(k.sideSeam({ x: mx - 1.6, y: g.y + 2.9, w: 3.2, d: 3.2, r: 1.2 }, W.ramZ - 6, P, 3), { tone: "faint" }) }));
  return out.join("");
}
